    }

    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;

    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
            <div className={`${bgColor} ${textColor} text-xs px-3 py-1.5 rounded-full shadow-lg backdrop-blur-sm border border-white/20 whitespace-nowrap flex items-center gap-2 font-bold transform -translate-y-2`}>
                {displayText}
            </div>
        </Html>
    );
};

const useShapeDrag = (
    shape: IShape,
    shapes: IShape[],
    isSelected: boolean,
    tool: ToolType,
    updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void,
    setDraggingState: (isDragging: boolean) => void,
    selectedIds: string[],
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>,
    setAlignmentLines: (lines: AlignmentLine[]) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({
        startPoint: new THREE.Vector3(),
        originalPositions: {} as Record<string, THREE.Vector3>,
        isDragging: false
    });

    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2(
            (clientX / gl.domElement.clientWidth) * 2 - 1,
            -(clientY / gl.domElement.clientHeight) * 2 + 1
        );
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };

    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const rawDelta = new THREE.Vector3().subVectors(intersect, dragInfo.current.startPoint);

             // Base snap calculations on the *primary* shape being dragged (this one)
             const myOriginalPos = dragInfo.current.originalPositions[shape.id];
             if (!myOriginalPos) return;

             const targetPos = new THREE.Vector3().addVectors(myOriginalPos, rawDelta);

             // Default Grid Snap
             let snappedX = Math.round(targetPos.x / SNAP_GRID) * SNAP_GRID;
             let snappedZ = Math.round(targetPos.z / SNAP_GRID) * SNAP_GRID;

             const newLines: AlignmentLine[] = [];

             // Alignment Snapping
             // We want to check if the current shape (projected to targetPos) aligns with other shapes
             const myBoundsRaw = getShapeBounds(shape, new THREE.Vector3(targetPos.x, myOriginalPos.y, targetPos.z));

             // X Axis Alignment Logic (Matches Z lines)
             let bestXDist = ALIGN_THRESHOLD;
             let bestXVal: number | null = null;
             let xMatchLine: AlignmentLine | null = null;

             // Z Axis Alignment Logic (Matches X lines)
             let bestZDist = ALIGN_THRESHOLD;
             let bestZVal: number | null = null;
             let zMatchLine: AlignmentLine | null = null;

             for (const other of shapes) {
                 if (selectedIds.includes(other.id)) continue; // Skip self or selected group

                 const otherBounds = getShapeBounds(other);

                 // --- X Axis Alignment (Vertical lines in top view, constant X) ---
                 // Sources on my shape: CenterX, MinX, MaxX
                 // Targets on other shape: CenterX, MinX, MaxX
                 const xSources = [myBoundsRaw.centerX, myBoundsRaw.minX, myBoundsRaw.maxX];
                 const xTargets = [otherBounds.centerX, otherBounds.minX, otherBounds.maxX];

                 for (const src of xSources) {
                     for (const tgt of xTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestXDist) {
                             bestXDist = dist;
                             // Correct the raw targetPos.x by the delta needed to align
                             bestXVal = targetPos.x - (src - tgt);

                             // Guide Line: Constant X, span Z range
                             const minZ = Math.min(myBoundsRaw.minZ, otherBounds.minZ) - 1;
                             const maxZ = Math.max(myBoundsRaw.maxZ, otherBounds.maxZ) + 1;
                             xMatchLine = [
                                 new THREE.Vector3(tgt, 0, minZ),
                                 new THREE.Vector3(tgt, 0, maxZ)
                             ];
                         }
                     }
                 }

                 // --- Z Axis Alignment (Horizontal lines in top view, constant Z) ---
                 const zSources = [myBoundsRaw.centerZ, myBoundsRaw.minZ, myBoundsRaw.maxZ];
                 const zTargets = [otherBounds.centerZ, otherBounds.minZ, otherBounds.maxZ];

                 for (const src of zSources) {
                     for (const tgt of zTargets) {
                         const dist = Math.abs(src - tgt);
                         if (dist < bestZDist) {
                             bestZDist = dist;
                             // Correct the raw targetPos.z by the delta needed to align
                             bestZVal = targetPos.z - (src - tgt);

                             // Guide Line: Constant Z, span X range
                             const minX = Math.min(myBoundsRaw.minX, otherBounds.minX) - 1;
                             const maxX = Math.max(myBoundsRaw.maxX, otherBounds.maxX) + 1;
                             zMatchLine = [
                                 new THREE.Vector3(minX, 0, tgt),
                                 new THREE.Vector3(maxX, 0, tgt)
                             ];
                         }
                     }
                 }
             }

             if (bestXVal !== null) {
                 snappedX = bestXVal;
                 if (xMatchLine) newLines.push(xMatchLine);
             }
             if (bestZVal !== null) {
                 snappedZ = bestZVal;
                 if (zMatchLine) newLines.push(zMatchLine);
             }

             setAlignmentLines(newLines);

             const snappedPos = new THREE.Vector3(snappedX, myOriginalPos.y, snappedZ);
             const effectiveDelta = new THREE.Vector3().subVectors(snappedPos, myOriginalPos);

             // Apply effectiveDelta to ALL selected objects
             Object.entries(dragInfo.current.originalPositions).forEach(([id, origPos]) => {
                 const ref = shapeRefs.current[id];
                 if (ref) {
                     ref.position.copy(origPos).add(effectiveDelta);
                 }
             });
        }
    }, [camera, gl, shape.id, shapes, selectedIds]); // Add shapes dependency for alignment check

    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;

        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        setAlignmentLines([]); // Clear guides
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);

        // Batch update all moved shapes
        const updates = Object.keys(dragInfo.current.originalPositions).map(id => {
            const ref = shapeRefs.current[id];
            if (ref) {
                 return {
                     id,
                     changes: { position: [ref.position.x, ref.position.y, ref.position.z] as [number, number, number] }
                 };
            }
            return null;
        }).filter(Boolean) as { id: string, changes: Partial<IShape> }[];

        if (updates.length > 0) {
            updateShapes(updates);
        }
    }, [handlePointerMove, updateShapes, setDraggingState, setAlignmentLines]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();

        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.startPoint.copy(intersect);

            // Fix: Logic to determine IDs to move
            // If the object is NOT selected yet (e.g. click-drag on new shape), we must calculate the group members manually
            // because selectedIds state might not have updated yet or is empty.
            let idsToMove: string[] = [];

            if (isSelected) {
                idsToMove = [...selectedIds];
            } else {
                if (shape.groupId) {
                    idsToMove = shapes.filter(s => s.groupId === shape.groupId).map(s => s.id);
                } else {
                    idsToMove = [shape.id];
                }
            }

            // Safety ensure current shape is included
            if (!idsToMove.includes(shape.id)) idsToMove.push(shape.id);

            const origins: Record<string, THREE.Vector3> = {};
            idsToMove.forEach(id => {
                const ref = shapeRefs.current[id];
                if (ref) {
                    origins[id] = ref.position.clone();
                }
            });
            dragInfo.current.originalPositions = origins;

            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, shapes, camera, gl, handlePointerMove, handlePointerUp, setDraggingState, isSelected, selectedIds]);

    useEffect(() => {
        return () => {
             window.removeEventListener('pointermove', handlePointerMove);
             window.removeEventListener('pointerup', handlePointerUp);
        };
    }, [handlePointerMove, handlePointerUp]);

    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers, setDraggingState, setShapeRef, shapeRefs, setAlignmentLines }: ShapeRendererProps & { shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>, setAlignmentLines: (lines: AlignmentLine[]) => void }) => {
    const { unit, tool, updateShapes, layers, selectedIds, shapes } = useApp();

    // Check Layer Visibility
    const parentLayer = layers.find(l => l.id === shape.layerId);
    if (parentLayer && !parentLayer.visible) return null;

    if (shape.type === 'dimension') {
        return (
            <DimensionShape 
                shape={shape} 
                isSelected={isSelected} 
                onSelect={(e) => {
                     if (!isSelected) onSelect(e);
                }} 
            />
        );
    }

    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);

    const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);

    // Register Ref
    useLayoutEffect(() => {
        setShapeRef(groupRef.current);
        return () => setShapeRef(null);
    }, [setShapeRef, shape.id]);

    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;

    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) {
        scaleY = pushPullState.dragHeight / shape.height;
    }

    const shape2D = useMemo(() => createThreeShape(shape.points), [shape.points]);

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 

            onPointerDown={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerDown(e);
                } else if (tool === ToolType.SELECT) {
                    if (!isSelected) {
                        onSelect(e);
                    }
                    handlePointerDown(e);
                } else {
                    drawingHandlers.handlePointerDown(e);
                }
            }}
            onPointerMove={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerMove(e);
                }
            }}
            onPointerUp={(e) => {
                if (isPushPullMode) {
                    pushPullHandlers.handlePointerUp();
                } else {
                    drawingHandlers.handlePointerUp(e);
                }
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial 
                    color={highlightColor} 
                    transparent={shape.type === 'flat'} 
                    opacity={shape.type === 'flat' ? 0.6 : 1.0} 
                    polygonOffset={shape.type === 'flat'} 
                    polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} 
                />
                <Edges 
                    color="#333" 
                    threshold={15}
                    renderOrder={1000}
                    visible={!isPushPullMode}
                />
            </mesh>
        </group>
    );
});

// ... Gizmo & Helper Components ...
const SelectionGizmo: React.FC = () => {
    const { selectedIds, transformMode, updateShape, tool } = useApp();
    const { scene, camera } = useThree();
    const [targetObj, setTargetObj] = useState<THREE.Object3D | null>(null);
    const isEnabled = tool === ToolType.SELECT && selectedIds.length === 1;
    const selectedId = isEnabled ? selectedIds[0] : null;
    useFrame(() => {
        if (!isEnabled || !selectedId) {
             if (targetObj) setTargetObj(null);
             return;
        }
        if (targetObj && targetObj.userData?.id === selectedId) return;
        let found: THREE.Object3D | null = null;
        scene.traverse((child) => {
            if (found) return;
            if (child.userData?.isShape && child.userData?.id === selectedId && child.userData?.isContainer) {
                found = child;
            }
        });
        if (found && found !== targetObj) {
            setTargetObj(found);
        }
    });
    if (!isEnabled || !targetObj) return null;
    return (
        <TransformControls 
            object={targetObj} 
            mode={transformMode} 
            space={transformMode === 'scale' ? 'local' : 'world'} 
            makeDefault 
            onDraggingChange={(isDragging) => {
                const controls = (camera as any).controls;
                if(controls) controls.enabled = !isDragging;
            }}
            onMouseUp={() => {
                 if (targetObj) {
                     updateShape(selectedId!, {
                         position: [targetObj.position.x, targetObj.position.y, targetObj.position.z],
                         rotation: targetObj.rotation.y,
                         scale: [targetObj.scale.x, targetObj.scale.y, targetObj.scale.z]
                     });
                 }
            }}
        />
    );
};

const CameraHandler: React.FC<{ view: string | null; onFinished: () => void }> = ({ view, onFinished }) => {
    const { camera, controls } = useThree();
    useEffect(() => {
        if (!view) return;
        let targetPos = new THREE.Vector3();
        const DISTANCE = 20;

        switch (view) {
            case 'top': targetPos.set(0, DISTANCE, 0); break;
            case 'bottom': targetPos.set(0, -DISTANCE, 0); break;
            case 'front': targetPos.set(0, 0, DISTANCE); break;
            case 'back': targetPos.set(0, 0, -DISTANCE); break;
            case 'right': targetPos.set(DISTANCE, 0, 0); break;
            case 'left': targetPos.set(-DISTANCE, 0, 0); break;
            default: return;
        }

        camera.position.copy(targetPos);
        camera.lookAt(0, 0, 0);
        if (controls) {
            const c = controls as any;
            if (c.target && typeof c.target.set === 'function') {
                c.target.set(0, 0, 0);
                c.update();
            }
        }
        onFinished();
    }, [view, camera, controls, onFinished]);
    return null;
};

