import React, { createContext, useContext, useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { IShape, ToolType, IPoint, TransformMode, ILayer, IGuideLine } from '../types';
import { DEFAULT_HEIGHT, DEFAULT_COLOR } from '../constants';

type UnitType = 'm' | 'cm';

interface AppContextType {
  // Project Info
  projectName: string;
  setProjectName: (name: string) => void;

  // Shapes
  shapes: IShape[];
  addShape: (shape: IShape) => void;
  updateShape: (id: string, updates: Partial<IShape>) => void;
  updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void;
  removeShape: (id: string) => void;
  removeSelected: () => void;
  replaceShapes: (idsToRemove: string[], newShapes: IShape[]) => void;
  copySelected: () => void;
  groupSelected: () => void;
  ungroupSelected: () => void;

  // Guide Lines
  guideLines: IGuideLine[];
  addGuideLine: (line: IGuideLine) => void;
  clearGuideLines: () => void;

  // Layers
  layers: ILayer[];
  activeLayerId: string;
  setActiveLayerId: (id: string) => void;
  addLayer: (name: string) => void;
  removeLayer: (id: string) => void;
  toggleLayerVisibility: (id: string) => void;
  updateLayerName: (id: string, name: string) => void;

  // Selection
  selectedIds: string[];
  selectShape: (id: string, multi?: boolean) => void;
  deselectAll: () => void;
  selectedId: string | null; 
  setSelectedId: (id: string | null) => void;

  // Tools & State
  tool: ToolType;
  setTool: (tool: ToolType) => void;
  transformMode: TransformMode;
  setTransformMode: (mode: TransformMode) => void;
  clearScene: () => void;
  addAIShapes: (items: any[]) => void;
  unit: UnitType;
  setUnit: (unit: UnitType) => void;
  formatValue: (val: number) => string;
  undo: () => void;
  redo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  wallThickness: number;
  setWallThickness: (val: number) => void;

  // File I/O
  saveProject: () => void;
  openProject: (file: File) => void;
  exportImage: () => void;

  // UI Toggles
  isLayerPanelOpen: boolean;
  setLayerPanelOpen: (open: boolean) => void;

  // Measurement
  setMeasurement: (val: string) => void;
  subscribeMeasurement: (cb: (val: string) => void) => () => void;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

const DEFAULT_LAYERS: ILayer[] = [
    { id: 'layer-structure', name: '結構 (柱/樑/牆)', visible: true, locked: false },
    { id: 'layer-partition', name: '輕隔間', visible: true, locked: false },
    { id: 'layer-furniture', name: '家具/設備', visible: true, locked: false },
    { id: 'layer-annotation', name: '標註/文字', visible: true, locked: false },
];

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  // History State
  const [history, setHistory] = useState<{shapes: IShape[], layers: ILayer[], guideLines: IGuideLine[]}[]>([{ shapes: [], layers: DEFAULT_LAYERS, guideLines: [] }]);
  const [historyIndex, setHistoryIndex] = useState(0);

  const [projectName, setProjectName] = useState('未命名專案');
  const [shapes, setShapes] = useState<IShape[]>([]);
  const [guideLines, setGuideLines] = useState<IGuideLine[]>([]);
  const [layers, setLayers] = useState<ILayer[]>(DEFAULT_LAYERS);
  const [activeLayerId, setActiveLayerId] = useState<string>('layer-structure');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [tool, setTool] = useState<ToolType>(ToolType.SELECT);
  const [transformMode, setTransformMode] = useState<TransformMode>('translate');
  const [unit, setUnit] = useState<UnitType>('cm');
  const [wallThickness, setWallThickness] = useState<number>(0.01);
  const [isLayerPanelOpen, setLayerPanelOpen] = useState(false);

  // Measurement Listeners
  const measurementListeners = useRef<Set<(val: string) => void>>(new Set());

  const setMeasurement = useCallback((val: string) => {
    measurementListeners.current.forEach(cb => cb(val));
  }, []);

  const subscribeMeasurement = useCallback((cb: (val: string) => void) => {
    measurementListeners.current.add(cb);
    return () => {
        measurementListeners.current.delete(cb);
    };
  }, []);

  // Internal helper to commit changes to history
  const _commitState = (newShapes: IShape[], newLayers: ILayer[], newGuideLines: IGuideLine[]) => {
    const newHistory = history.slice(0, historyIndex + 1);
    newHistory.push({ shapes: newShapes, layers: newLayers, guideLines: newGuideLines });
    setHistory(newHistory);
    setHistoryIndex(newHistory.length - 1);
    setShapes(newShapes);
    setLayers(newLayers);
    setGuideLines(newGuideLines);
  };

  const undo = useCallback(() => {
    if (historyIndex > 0) {
      const newIndex = historyIndex - 1;
      setHistoryIndex(newIndex);
      setShapes(history[newIndex].shapes);
      setLayers(history[newIndex].layers);
      setGuideLines(history[newIndex].guideLines);
      setSelectedIds([]);
    }
  }, [history, historyIndex]);

  const redo = useCallback(() => {
    if (historyIndex < history.length - 1) {
      const newIndex = historyIndex + 1;
      setHistoryIndex(newIndex);
      setShapes(history[newIndex].shapes);
      setLayers(history[newIndex].layers);
      setGuideLines(history[newIndex].guideLines);
      setSelectedIds([]);
    }
  }, [history, historyIndex]);

  // --- Layer Logic ---
  const addLayer = useCallback((name: string) => {
      const newLayer: ILayer = {
          id: `layer-${Date.now()}`,
          name: name || '新圖層',
          visible: true,
          locked: false
      };
      const newLayers = [...layers, newLayer];
      _commitState(shapes, newLayers, guideLines);
      setActiveLayerId(newLayer.id);
  }, [layers, shapes, guideLines, historyIndex, history]);

  const removeLayer = useCallback((id: string) => {
      if (layers.length <= 1) return; // Prevent deleting last layer
      const newLayers = layers.filter(l => l.id !== id);
      // Move shapes from deleted layer to the first available layer
      const fallbackLayerId = newLayers[0].id;
      const newShapes = shapes.map(s => s.layerId === id ? { ...s, layerId: fallbackLayerId } : s);

      if (activeLayerId === id) setActiveLayerId(fallbackLayerId);

      _commitState(newShapes, newLayers, guideLines);
  }, [layers, shapes, guideLines, activeLayerId, historyIndex, history]);

  const toggleLayerVisibility = useCallback((id: string) => {
      const newLayers = layers.map(l => l.id === id ? { ...l, visible: !l.visible } : l);
      setLayers(newLayers); 
  }, [layers]);

  const updateLayerName = useCallback((id: string, name: string) => {
      const newLayers = layers.map(l => l.id === id ? { ...l, name } : l);
      _commitState(shapes, newLayers, guideLines);
  }, [layers, shapes, guideLines, historyIndex, history]);


  // --- Shape Logic ---

  const addShape = useCallback((shape: IShape) => {
    // Ensure shape has a layer. If not provided, use active.
    const finalShape = { ...shape, layerId: shape.layerId || activeLayerId };
    const newShapes = [...shapes, finalShape];
    _commitState(newShapes, layers, guideLines);
    setSelectedIds([shape.id]);
  }, [shapes, layers, guideLines, activeLayerId, historyIndex, history]);

  const updateShape = useCallback((id: string, updates: Partial<IShape>) => {
    const newShapes = shapes.map(s => s.id === id ? { ...s, ...updates } : s);
    _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, historyIndex, history]);

  const updateShapes = useCallback((updates: { id: string; changes: Partial<IShape> }[]) => {
    const newShapes = shapes.map(s => {
      const update = updates.find(u => u.id === s.id);
      return update ? { ...s, ...update.changes } : s;
    });
    _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, historyIndex, history]);

  const removeShape = useCallback((id: string) => {
    const newShapes = shapes.filter(s => s.id !== id);
    _commitState(newShapes, layers, guideLines);
    if (selectedIds.includes(id)) setSelectedIds(prev => prev.filter(pid => pid !== id));
  }, [shapes, layers, guideLines, selectedIds, historyIndex, history]);

  const removeSelected = useCallback(() => {
    if (selectedIds.length === 0) return;
    const newShapes = shapes.filter(s => !selectedIds.includes(s.id));
    _commitState(newShapes, layers, guideLines);
    setSelectedIds([]);
  }, [shapes, layers, guideLines, selectedIds, historyIndex, history]);

  const replaceShapes = useCallback((idsToRemove: string[], newShapes: IShape[]) => {
    const filteredCurrent = shapes.filter(s => !idsToRemove.includes(s.id));
    // Assign active layer to new shapes if they don't have one
    const labeledNewShapes = newShapes.map(s => ({ ...s, layerId: s.layerId || activeLayerId }));
    const combined = [...filteredCurrent, ...labeledNewShapes];
    _commitState(combined, layers, guideLines);
    if (newShapes.length === 1) setSelectedIds([newShapes[0].id]);
    else setSelectedIds([]);
  }, [shapes, layers, guideLines, activeLayerId, historyIndex, history]);

  const copySelected = useCallback(() => {
    if (selectedIds.length === 0) return;

    const groupMapping: Record<string, string> = {};

    const newShapesToAdd = shapes
      .filter(s => selectedIds.includes(s.id))
      .map(s => {
         let newGroupId = undefined;
         if (s.groupId) {
             if (!groupMapping[s.groupId]) {
                 groupMapping[s.groupId] = `group-${Date.now()}-${Math.random()}`;
             }
             newGroupId = groupMapping[s.groupId];
         }

         return {
            ...s,
            id: `copy-${Date.now()}-${Math.random()}`,
            groupId: newGroupId,
            name: `${s.name}`,
            position: [s.position[0] + 1, s.position[1], s.position[2] + 1] as [number, number, number]
         };
      });

    const newShapes = [...shapes, ...newShapesToAdd];
    _commitState(newShapes, layers, guideLines);
    setSelectedIds(newShapesToAdd.map(s => s.id));
  }, [shapes, layers, guideLines, selectedIds, historyIndex, history]);

  const groupSelected = useCallback(() => {
      if (selectedIds.length < 2) return;
      const newGroupId = `group-${Date.now()}`;

      const updates = selectedIds.map(id => ({
          id,
          changes: { groupId: newGroupId }
      }));
      updateShapes(updates);
  }, [selectedIds, updateShapes]);

  const ungroupSelected = useCallback(() => {
      if (selectedIds.length === 0) return;
      const updates = selectedIds.map(id => ({
          id,
          changes: { groupId: undefined }
      }));
      updateShapes(updates);
  }, [selectedIds, updateShapes]);

  // --- Guide Lines Logic ---
  const addGuideLine = useCallback((line: IGuideLine) => {
      const newGuideLines = [...guideLines, line];
      _commitState(shapes, layers, newGuideLines);
  }, [guideLines, shapes, layers, historyIndex, history]);

  const clearGuideLines = useCallback(() => {
      _commitState(shapes, layers, []);
  }, [shapes, layers, historyIndex, history]);

  const clearScene = useCallback(() => {
    _commitState([], DEFAULT_LAYERS, []);
    setSelectedIds([]);
  }, [historyIndex, history]);

  const addAIShapes = useCallback((items: any[]) => {
    const newGeneratedShapes: IShape[] = items.map((item, index) => {
      const w = item.width / 2;
      const d = item.depth / 2;
      const points: IPoint[] = [
        { x: -w, y: 0, z: -d },
        { x: w, y: 0, z: -d },
        { x: w, y: 0, z: d },
        { x: -w, y: 0, z: d },
        { x: -w, y: 0, z: -d },
      ];

      return {
        id: `ai-${Date.now()}-${index}`,
        layerId: 'layer-furniture', // Default AI to furniture
        type: 'solid',
        name: item.name,
        points,
        height: item.height,
        color: item.color || DEFAULT_COLOR,
        position: [item.x, 0, item.z],
        rotation: 0,
        scale: [1, 1, 1]
      };
    });

    const newShapes = [...shapes, ...newGeneratedShapes];
    _commitState(newShapes, layers, guideLines);
  }, [shapes, layers, guideLines, historyIndex, history]);

  const formatValue = useCallback((val: number) => {
    if (unit === 'cm') {
      return `${(val * 100).toFixed(0)} cm`;
    }
    return `${val.toFixed(2)} m`;
  }, [unit]);

  const selectShape = useCallback((id: string, multi = false) => {
      const targetShape = shapes.find(s => s.id === id);
      if (!targetShape) return;

      // Ensure we don't select hidden shapes
      const targetLayer = layers.find(l => l.id === targetShape.layerId);
      if (targetLayer && !targetLayer.visible) return;

      let idsToToggle = [id];
      if (targetShape.groupId) {
          idsToToggle = shapes.filter(s => s.groupId === targetShape.groupId).map(s => s.id);
      }

      if (multi) {
          const allSelected = idsToToggle.every(tid => selectedIds.includes(tid));
          if (allSelected) {
              setSelectedIds(prev => prev.filter(pid => !idsToToggle.includes(pid)));
          } else {
              const newSet = new Set([...selectedIds, ...idsToToggle]);
              setSelectedIds(Array.from(newSet));
          }
      } else {
          setSelectedIds(idsToToggle);
      }
  }, [shapes, layers, selectedIds]);

  const deselectAll = useCallback(() => {
      setSelectedIds([]);
  }, []);

  // --- File I/O ---
  const saveProject = useCallback(() => {
      const data = {
          version: '1.0.0',
          projectName,
          shapes,
          layers,
          activeLayerId,
          guideLines
      };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${projectName}.json`;
      a.click();
      URL.revokeObjectURL(url);
  }, [projectName, shapes, layers, activeLayerId, guideLines]);

  const openProject = useCallback((file: File) => {
      const reader = new FileReader();
      reader.onload = (e) => {
          try {
              const json = JSON.parse(e.target?.result as string);
              if (json.shapes && Array.isArray(json.shapes)) {
                  // Migration for old files: add layerId if missing
                  const migratedShapes = json.shapes.map((s: any) => ({
                      ...s,
                      layerId: s.layerId || DEFAULT_LAYERS[0].id
                  }));

                  setProjectName(json.projectName || '匯入的專案');
                  setShapes(migratedShapes);
                  if (json.layers) setLayers(json.layers);
                  if (json.activeLayerId) setActiveLayerId(json.activeLayerId);
                  if (json.guideLines) setGuideLines(json.guideLines);

                  // Reset history
                  setHistory([{ shapes: migratedShapes, layers: json.layers || DEFAULT_LAYERS, guideLines: json.guideLines || [] }]);
                  setHistoryIndex(0);
                  setSelectedIds([]);
              }
          } catch (err) {
              console.error("Invalid file format", err);
              alert("檔案格式錯誤");
          }
      };
      reader.readAsText(file);
  }, []);

  const exportImage = useCallback(() => {
      const canvas = document.querySelector('canvas');
      if (canvas) {
          const link = document.createElement('a');
          link.download = `${projectName}.png`;
          link.href = canvas.toDataURL('image/png');
          link.click();
      }
  }, [projectName]);

  return (
    <AppContext.Provider value={{
      projectName,
      setProjectName,
      shapes,
      addShape,
      updateShape,
      updateShapes,
      removeShape,
      removeSelected,
      replaceShapes,
      copySelected,
      groupSelected,
      ungroupSelected,
      selectedIds,
      selectShape,
      deselectAll,
      selectedId: selectedIds.length > 0 ? selectedIds[selectedIds.length - 1] : null,
      setSelectedId: (id) => id ? selectShape(id) : deselectAll(),
      tool,
      setTool,
      transformMode,
      setTransformMode,
      clearScene,
      addAIShapes,
      unit,
      setUnit,
      formatValue,
      undo,
      redo,
      canUndo: historyIndex > 0,
      canRedo: historyIndex < history.length - 1,
      wallThickness,
      setWallThickness,
      setMeasurement,
      subscribeMeasurement,

      layers,
      activeLayerId,
      setActiveLayerId,
      addLayer,
      removeLayer,
      toggleLayerVisibility,
      updateLayerName,

      guideLines,
      addGuideLine,
      clearGuideLines,

      saveProject,
      openProject,
      exportImage,

      isLayerPanelOpen,
      setLayerPanelOpen
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

import React, { useRef, useState, useMemo, useEffect, useCallback, useLayoutEffect } from 'react';
import { Canvas, useThree, ThreeEvent, useFrame } from '@react-three/fiber';
import { OrbitControls, Grid, TransformControls, Html, GizmoHelper, GizmoViewport, Edges, Text, Billboard } from '@react-three/drei';
import * as THREE from 'three';
import { useApp } from '../context/AppContext';
import { ToolType, IPoint, IShape, IGuideLine } from '../types';
import { SNAP_GRID, DEFAULT_COLOR, FLAT_COLOR, HIGHLIGHT_COLOR, DEFAULT_HEIGHT } from '../constants';
import AIAssistant from './AIAssistant';

// --- Constants ---
const SNAP_THRESHOLD = 0.3; // Ray distance threshold
const ALIGN_THRESHOLD = 0.3;
const EPSILON = 1e-4;

// --- Types ---
type SnapType = 'none' | 'grid' | 'vertex' | 'midpoint' | 'edge' | 'face' | 'align' | 'endpoint';
type AlignmentLine = [THREE.Vector3, THREE.Vector3];

interface SnapResult {
    position: THREE.Vector3;
    type: SnapType;
    distance: number;
    snapObjectId?: string;
    snapEdge?: [THREE.Vector3, THREE.Vector3];
}

type PushPullMode = 'top' | 'side' | 'none';

interface PushPullState {
    mode: PushPullMode;
    hoveredShapeId: string | null;
    hoveredEdgeIndex: number;
    dragStartPoint: THREE.Vector3 | null;
    originalHeight: number;
    originalPoints: IPoint[];
    normal: THREE.Vector3;
    dragHeight?: number;
}

interface ShapeRendererProps {
    shape: IShape;
    isSelected: boolean;
    onSelect: (e: ThreeEvent<MouseEvent>) => void;
    pushPullState: PushPullState;
    pushPullHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: () => void;
        handlePointerMove: (e: ThreeEvent<PointerEvent>) => void;
    };
    drawingHandlers: {
        handlePointerDown: (e: ThreeEvent<PointerEvent>) => void;
        handlePointerUp: (e: ThreeEvent<PointerEvent>) => void;
        handleClick: (e: ThreeEvent<MouseEvent>) => void;
    };
    setDraggingState: (isDragging: boolean) => void;
    setShapeRef: (ref: THREE.Group | null) => void; 
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>;
    setAlignmentLines: (lines: AlignmentLine[]) => void;
}

// --- Geometry Helpers ---
const createThreeShape = (points: IPoint[]) => {
  const shape = new THREE.Shape();
  if (!points || points.length === 0) return shape;
  if (points[0]) {
    shape.moveTo(points[0].x, -points[0].z); 
    for (let i = 1; i < points.length; i++) {
        if (points[i]) shape.lineTo(points[i].x, -points[i].z);
    }
  }
  shape.closePath();
  return shape;
};

const createCirclePoints = (radius: number, segments = 32): IPoint[] => {
  const points: IPoint[] = [];
  for (let i = 0; i < segments; i++) {
    const theta = (i / segments) * Math.PI * 2;
    points.push({ x: Math.cos(theta) * radius, y: 0, z: Math.sin(theta) * radius });
  }
  points.push(points[0]);
  return points;
};

const transformPoint = (localP: IPoint, shape: IShape): THREE.Vector3 => {
    const sX = shape.scale[0];
    const sZ = shape.scale[2];
    const rot = shape.rotation;
    const cos = Math.cos(rot);
    const sin = Math.sin(rot);
    const xScaled = localP.x * sX;
    const zScaled = localP.z * sZ;
    const xRot = xScaled * cos - zScaled * sin;
    const zRot = xScaled * sin + zScaled * cos;
    return new THREE.Vector3(xRot + shape.position[0], shape.position[1], zRot + shape.position[2]);
};

// Helper to get Axis-Aligned Bounding Box (AABB) of a shape at a specific position
const getShapeBounds = (shape: IShape, currentPos?: THREE.Vector3) => {
    const pos = currentPos || new THREE.Vector3(...shape.position);
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;

    // Create a temporary shape object with the new position to reuse transformPoint logic
    // We only need position, rotation, scale.
    const tempShape = { ...shape, position: [pos.x, pos.y, pos.z] };

    shape.points.forEach(p => {
         const wp = transformPoint(p, tempShape as IShape);
         if(wp.x < minX) minX = wp.x;
         if(wp.x > maxX) maxX = wp.x;
         if(wp.z < minZ) minZ = wp.z;
         if(wp.z > maxZ) maxZ = wp.z;
    });

    return {
        minX, maxX, minZ, maxZ,
        centerX: (minX + maxX) / 2,
        centerZ: (minZ + maxZ) / 2,
        y: pos.y
    };
};

const closestPointOnSegment = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3): THREE.Vector3 => {
  const vwx = w.x - v.x;
  const vwy = w.y - v.y;
  const vwz = w.z - v.z;
  const vpx = p.x - v.x;
  const vpy = p.y - v.y;
  const vpz = p.z - v.z;
  const dot = vpx * vwx + vpy * vwy + vpz * vwz;
  const l2 = vwx * vwx + vwy * vwy + vwz * vwz;
  if (l2 === 0) return v;
  let t = dot / l2;
  t = Math.max(0, Math.min(1, t));
  return new THREE.Vector3(v.x + t * vwx, v.y + t * vwy, v.z + t * vwz);
};

const distToSegmentSquared = (p: THREE.Vector3, v: THREE.Vector3, w: THREE.Vector3) => {
    const l2 = v.distanceToSquared(w);
    if (l2 === 0) return p.distanceToSquared(v);
    let t = ((p.x - v.x) * (w.x - v.x) + (p.z - v.z) * (w.z - v.z)) / l2;
    t = Math.max(0, Math.min(1, t));
    return (p.x - (v.x + t * (w.x - v.x)))**2 + (p.z - (v.z + t * (w.z - v.z)))**2;
};

// Robust Line Intersection (Infinite Lines)
const getLineIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null; // Parallel
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;
    return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
};

// Segment Intersection (Strict, returns null if no intersection on segments)
const getSegmentIntersection = (p1: IPoint, p2: IPoint, p3: IPoint, p4: IPoint): IPoint | null => {
    const d = (p2.x - p1.x) * (p4.z - p3.z) - (p2.z - p1.z) * (p4.x - p3.x);
    if (Math.abs(d) < EPSILON) return null;
    const u = ((p3.x - p1.x) * (p4.z - p3.z) - (p3.z - p1.z) * (p4.x - p3.x)) / d;
    const v = ((p3.x - p1.x) * (p2.z - p1.z) - (p3.z - p1.z) * (p2.x - p1.x)) / d;

    // Check if intersection is strictly within both segments
    if (u >= -EPSILON && u <= 1 + EPSILON && v >= -EPSILON && v <= 1 + EPSILON) {
        return { x: p1.x + u * (p2.x - p1.x), y: 0, z: p1.z + u * (p2.z - p1.z) };
    }
    return null;
};

// --- Polygon Cutting Algorithm ---
// Cuts a polygon by an infinite line defined by lineStart -> lineEnd (segment)
const cutPolygonBySegment = (polyPoints: IPoint[], lineStart: IPoint, lineEnd: IPoint): [IPoint[], IPoint[]] | null => {
    interface Intersection {
        point: IPoint;
        edgeIndex: number; // The index of the polygon edge starting point
        dist: number; // Distance from lineStart (for sorting)
    }

    const intersections: Intersection[] = [];

    // 1. Find all intersections between the cut segment and polygon edges
    for (let i = 0; i < polyPoints.length; i++) {
        const p1 = polyPoints[i];
        const p2 = polyPoints[(i + 1) % polyPoints.length];

        const hit = getSegmentIntersection(p1, p2, lineStart, lineEnd);

        if (hit) {
            // Avoid duplicate points
            const isDuplicate = intersections.some(
                intr => Math.abs(intr.point.x - hit.x) < 0.001 && Math.abs(intr.point.z - hit.z) < 0.001
            );
            if (!isDuplicate) {
                const dist = Math.sqrt((hit.x - lineStart.x)**2 + (hit.z - lineStart.z)**2);
                intersections.push({ point: hit, edgeIndex: i, dist });
            }
        }
    }

    // We need exactly 2 intersection points for a simple split
    if (intersections.length < 2) return null;

    // Sort by distance along the cut line
    intersections.sort((a, b) => a.dist - b.dist);

    // Take the first two (entry and exit)
    const [startHit, endHit] = intersections;

    const getVerticesBetween = (idx1: number, idx2: number) => {
        const verts: IPoint[] = [];
        let i = (idx1 + 1) % polyPoints.length;
        while (i !== (idx2 + 1) % polyPoints.length) {
            verts.push(polyPoints[i]);
            i = (i + 1) % polyPoints.length;
        }
        return verts;
    };

    const polyA_verts = getVerticesBetween(startHit.edgeIndex, endHit.edgeIndex);
    const polyA = [startHit.point, ...polyA_verts, endHit.point];

    const polyB_verts = getVerticesBetween(endHit.edgeIndex, startHit.edgeIndex);
    const polyB = [endHit.point, ...polyB_verts, startHit.point];

    return [polyA, polyB];
};


const getLineEndpoints = (shape: IShape): [THREE.Vector3, THREE.Vector3] | null => {
    if (shape.name !== 'Edge') return null;

    let minX = Infinity, maxX = -Infinity;
    shape.points.forEach(p => {
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
    });

    const halfLen = (maxX - minX) / 2;
    const scaledHalfLen = halfLen * shape.scale[0];

    const pos = new THREE.Vector3(shape.position[0], shape.position[1], shape.position[2]);
    const angle = -shape.rotation; 

    const dx = Math.cos(angle) * scaledHalfLen;
    const dz = Math.sin(angle) * scaledHalfLen;

    const p1 = new THREE.Vector3(pos.x - dx, pos.y, pos.z - dz);
    const p2 = new THREE.Vector3(pos.x + dx, pos.y, pos.z + dz);

    return [p1, p2];
};

// --- Face Detection & Planar Graph Algorithms ---
const fragmentSegments = (segments: { start: IPoint; end: IPoint }[]): { start: IPoint; end: IPoint }[] => {
    let currentSegments = [...segments];
    let hasIntersections = true;
    let iterations = 0;

    while (hasIntersections && iterations < 50) {
        hasIntersections = false;
        iterations++;
        const newSegments: { start: IPoint; end: IPoint }[] = [];
        const processed = new Set<number>();

        for (let i = 0; i < currentSegments.length; i++) {
            if (processed.has(i)) continue;
            let s1 = currentSegments[i];
            let broken = false;

            for (let j = i + 1; j < currentSegments.length; j++) {
                if (processed.has(j)) continue;
                let s2 = currentSegments[j];

                const intersection = getSegmentIntersection(s1.start, s1.end, s2.start, s2.end);

                const isEndpoint = (p: IPoint, s: {start: IPoint, end: IPoint}) => 
                    (Math.abs(p.x - s.start.x) < 0.001 && Math.abs(p.z - s.start.z) < 0.001) ||
                    (Math.abs(p.x - s.end.x) < 0.001 && Math.abs(p.z - s.end.z) < 0.001);

                if (intersection && !isEndpoint(intersection, s1) && !isEndpoint(intersection, s2)) {
                    // Split s1
                    newSegments.push({ start: s1.start, end: intersection });
                    newSegments.push({ start: intersection, end: s1.end });
                    // Split s2
                    newSegments.push({ start: s2.start, end: intersection });
                    newSegments.push({ start: intersection, end: s2.end });

                    processed.add(i);
                    processed.add(j);
                    broken = true;
                    hasIntersections = true;
                    break; 
                }
            }
            if (!broken) {
                newSegments.push(s1);
            }
        }
        if (hasIntersections) {
            currentSegments = newSegments;
        }
    }
    return currentSegments;
};

const findClosedCycles = (segments: { start: IPoint; end: IPoint }[]): IPoint[][] => {
    const nodes: Record<string, { x: number, z: number, neighbors: string[] }> = {};
    const key = (p: IPoint) => `${p.x.toFixed(3)},${p.z.toFixed(3)}`;
    const addNode = (p: IPoint) => {
        const k = key(p);
        if (!nodes[k]) nodes[k] = { x: p.x, z: p.z, neighbors: [] };
        return k;
    };

    // Build Graph
    segments.forEach(s => {
        if (Math.abs(s.start.x - s.end.x) < 0.001 && Math.abs(s.start.z - s.end.z) < 0.001) return;
        const k1 = addNode(s.start);
        const k2 = addNode(s.end);
        if (!nodes[k1].neighbors.includes(k2)) nodes[k1].neighbors.push(k2);
        if (!nodes[k2].neighbors.includes(k1)) nodes[k2].neighbors.push(k1);
    });

    const cycles: IPoint[][] = [];
    const visitedEdges = new Set<string>();

    Object.keys(nodes).forEach(uKey => {
        const uNode = nodes[uKey];
        // Sort neighbors by angle
        uNode.neighbors.sort((aKey, bKey) => {
            const aNode = nodes[aKey];
            const bNode = nodes[bKey];
            const angA = Math.atan2(aNode.z - uNode.z, aNode.x - uNode.x);
            const angB = Math.atan2(bNode.z - uNode.z, bNode.x - uNode.x);
            return angA - angB;
        });

        uNode.neighbors.forEach(vKey => {
            const edgeKey = `${uKey}->${vKey}`;
            if (visitedEdges.has(edgeKey)) return;

            const path = [uKey];
            const pathSet = new Set([uKey]);
            let curr = vKey;
            let prev = uKey;
            let isCycle = false;

            // Turn Left Rule (CCW)
            const MAX_PATH = 50; 
            for(let i=0; i<MAX_PATH; i++) {
                visitedEdges.add(`${prev}->${curr}`);
                path.push(curr);

                if (curr === uKey) {
                    isCycle = true;
                    break;
                }

                if (pathSet.has(curr)) break; // Loop
                pathSet.add(curr);

                const currNode = nodes[curr];
                const neighbors = currNode.neighbors;
                const prevIdx = neighbors.indexOf(prev);
                const nextIdx = (prevIdx - 1 + neighbors.length) % neighbors.length;
                const nextKey = neighbors[nextIdx];

                if (!nextKey || nextKey === prev) break;

                prev = curr;
                curr = nextKey;
            }

            if (isCycle && path.length > 3) {
                const points = path.slice(0, -1).map(k => ({ x: nodes[k].x, y: 0, z: nodes[k].z }));

                // Calculate Area (Shoelace)
                let area = 0;
                for(let i=0; i<points.length; i++) {
                    const p1 = points[i];
                    const p2 = points[(i+1)%points.length];
                    area += (p2.x - p1.x) * (p2.z + p1.z);
                }

                if (Math.abs(area) > 0.01) {
                    cycles.push(points);
                }
            }
        });
    });

    // Deduplicate
    const uniqueCycles: IPoint[][] = [];
    const cycleFingerprints = new Set<string>();

    cycles.forEach(cycle => {
        let cx = 0, cz = 0;
        cycle.forEach(p => { cx += p.x; cz += p.z });
        cx /= cycle.length;
        cz /= cycle.length;
        const fingerprint = `${cx.toFixed(3)},${cz.toFixed(3)}_${cycle.length}`;
        if (!cycleFingerprints.has(fingerprint)) {
            cycleFingerprints.add(fingerprint);
            uniqueCycles.push(cycle);
        }
    });

    return uniqueCycles;
};


const getBoundingCenter = (points: IPoint[]) => {
    let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
    points.forEach(p => {
        if(p.x < minX) minX = p.x; if(p.x > maxX) maxX = p.x;
        if(p.z < minZ) minZ = p.z; if(p.z > maxZ) maxZ = p.z;
    });
    return { x: (minX + maxX) / 2, z: (minZ + maxZ) / 2 };
};

const getGeometrySnap = (
    cursorPos: THREE.Vector3, 
    ray: THREE.Ray,
    shapes: IShape[], 
    activePoints: IPoint[] = [],
    threshold: number,
    intersectedObject?: THREE.Intersection
): SnapResult => {

    // Default fallback (Grid or Face)
    let fallbackSnap: SnapResult;

    const getShapeUserData = (obj: THREE.Object3D) => {
        if (obj.userData?.isShape) return obj.userData;
        if (obj.parent?.userData?.isShape) return obj.parent.userData;
        return null;
    };
    const shapeData = intersectedObject ? getShapeUserData(intersectedObject.object) : null;

    if (intersectedObject && shapeData) {
        fallbackSnap = { 
            position: intersectedObject.point, 
            type: 'face', 
            distance: 0, 
            snapObjectId: shapeData.id 
        };
    } else {
        fallbackSnap = {
            position: new THREE.Vector3(
                Math.round(cursorPos.x / SNAP_GRID) * SNAP_GRID,
                cursorPos.y, 
                Math.round(cursorPos.z / SNAP_GRID) * SNAP_GRID
            ),
            type: 'grid',
            distance: Infinity
        };
    }

    // Candidates
    let bestVertexSnap: SnapResult | null = null;
    let bestEdgeSnap: SnapResult | null = null;
    let minVertexDist = threshold;
    let minEdgeDist = threshold;

    // 1. Check Active Points (Endpoint of current drawing) - High priority
    if (activePoints && activePoints.length > 0) {
        const startPt = activePoints[0];
        const ptVec = new THREE.Vector3(startPt.x, startPt.y, startPt.z);
        // Use ray distance for snapping to existing drawing start point
        const dist = ray.distanceToPoint(ptVec);
        if (dist < threshold * 1.5) {
            bestVertexSnap = { position: ptVec, type: 'endpoint', distance: dist };
            minVertexDist = dist;
        }
    }

    // 2. Check Vertices (Nodes) & Line Endpoints
    for (const shape of shapes) {
        // Line Endpoints
        if (shape.name === 'Edge') {
             const endpoints = getLineEndpoints(shape);
             if (endpoints) {
                 for(const ep of endpoints) {
                     // We use Ray Distance now, so Y check is less critical, but still good to avoid snapping to stuff behind camera if ray was infinite (Raycaster handles direction though)
                     const dist = ray.distanceToPoint(ep);
                     if (dist < minVertexDist) {
                         bestVertexSnap = { position: ep, type: 'endpoint', distance: dist, snapObjectId: shape.id };
                         minVertexDist = dist;
                     }
                 }
                 continue; 
             }
        }

        const currentH = shape.height * shape.scale[1];
        const hasHeight = Math.abs(currentH) > 0.001;

        // Shape Vertices
        for (let i = 0; i < shape.points.length; i++) {
            const worldPt = transformPoint(shape.points[i], shape);
            let dist = ray.distanceToPoint(worldPt);

            if (dist < minVertexDist) {
                bestVertexSnap = { position: worldPt, type: 'vertex', distance: dist, snapObjectId: shape.id };
                minVertexDist = dist;
            }
            if (hasHeight) {
                const worldPtTop = worldPt.clone().setY(worldPt.y + currentH);
                dist = ray.distanceToPoint(worldPtTop);
                if (dist < minVertexDist) {
                    bestVertexSnap = { position: worldPtTop, type: 'vertex', distance: dist, snapObjectId: shape.id };
                    minVertexDist = dist;
                }
            }
        }
    }

    // 3. Check Edges and Midpoints
    // Only check if we haven't found a *very* close vertex (optimization)
    if (!bestVertexSnap || bestVertexSnap.distance > 0.1) {
        for (const shape of shapes) {
            const pts = shape.points;
            const len = pts.length;
            const currentH = shape.height * shape.scale[1];
            const hasHeight = Math.abs(currentH) > 0.001;

            for (let i = 0; i < len; i++) {
                const p1 = transformPoint(pts[i], shape);
                const p2 = transformPoint(pts[(i + 1) % len], shape);

                const checkSegment = (v1: THREE.Vector3, v2: THREE.Vector3) => {
                    // Midpoint
                    const mid = new THREE.Vector3().addVectors(v1, v2).multiplyScalar(0.5);
                    const distMid = ray.distanceToPoint(mid);

                    if (distMid < minEdgeDist) {
                        bestEdgeSnap = { position: mid, type: 'midpoint', distance: distMid, snapObjectId: shape.id, snapEdge: [v1, v2] };
                        minEdgeDist = distMid;
                    }

                    // Edge Projection
                    // Find closest point on segment to the Ray
                    const pointOnSegment = new THREE.Vector3();
                    const distSq = ray.distanceSqToSegment(v1, v2, undefined, pointOnSegment);
                    const distEdge = Math.sqrt(distSq);

                    if (distEdge < minEdgeDist) {
                         if (bestEdgeSnap?.type === 'midpoint' && bestEdgeSnap.distance < distEdge + 0.1) {
                             // Keep midpoint
                         } else {
                             bestEdgeSnap = { position: pointOnSegment, type: 'edge', distance: distEdge, snapObjectId: shape.id, snapEdge: [v1, v2] };
                             minEdgeDist = distEdge;
                         }
                    }
                };

                checkSegment(p1, p2);
                if (hasHeight) {
                    const p1Top = p1.clone().setY(p1.y + currentH);
                    const p2Top = p2.clone().setY(p2.y + currentH);
                    checkSegment(p1Top, p2Top);
                    checkSegment(p1, p1Top);
                }
            }
        }
    }

    // Final Decision
    if (bestVertexSnap && bestEdgeSnap) {
        // Weighting: Vertex has preference
        if (bestVertexSnap.distance < bestEdgeSnap.distance * 1.5) {
            return bestVertexSnap;
        } else {
            return bestEdgeSnap;
        }
    }

    if (bestVertexSnap) return bestVertexSnap;
    if (bestEdgeSnap) return bestEdgeSnap;

    return fallbackSnap;
};

