                    selectShape('', false);
                }
            }} 
            onPointerUp={(e) => {
                 if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) handleDrawUp(e);
                 if (tool === ToolType.PUSH_PULL) handlePPUp(); 
            }}
            onPointerMove={(e) => {
                 if (tool === ToolType.PUSH_PULL) handlePPMove(e);
            }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow>
                <planeGeometry args={[1000, 1000]} />
                <meshBasicMaterial visible={false} /> 
            </mesh>
        </group>

        <group>
          {shapes.map(shape => (
            <ShapeRenderer
              key={shape.id}
              shape={shape}
              isSelected={selectedIds.includes(shape.id)}
              onSelect={(e) => {
                e.stopPropagation();
                const isMulti = e.nativeEvent.ctrlKey || e.nativeEvent.metaKey;
                selectShape(shape.id, isMulti);
              }}
              pushPullState={ppState}
              pushPullHandlers={{
                handlePointerDown: handlePPDown,
                handlePointerUp: handlePPUp,
                handlePointerMove: handlePPMove
              }}
              drawingHandlers={{
                handlePointerDown: handleDrawDown,
                handlePointerUp: handleDrawUp,
                handleClick: handleDrawClick
              }}
              setDraggingState={setIsShapeDragging}
              setShapeRef={(ref) => setShapeRef(shape.id, ref)}
              shapeRefs={shapeRefs}
              setAlignmentLines={setAlignmentLines}
            />
          ))}
        </group>

        {/* Interaction Layer - Handles Snapping & Drawing Preview */}
        <InteractionLayer
          shapes={shapes}
          tool={tool}
          setCursorPos={setDrawCursorPos}
          setSnapInfo={setDrawSnapInfo}
          cursorPos={drawCursorPos}
          snapInfo={drawSnapInfo}
          drawPoints={drawPoints}
          isDragging={isDrawDragging}
          drawingHeight={0}
          typedInput={typedInput}
          guideCreating={guideCreating}
        />

        <AlignmentLinesRenderer lines={alignmentLines} />

        {/* Render Committed Guide Lines */}
        <GuideLinesRenderer lines={guideLines} />

        <SelectionGizmo />

        <GizmoHelper alignment="bottom-right" margin={[80, 80]}>
          <GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" />
        </GizmoHelper>
        <CameraHandler view={view} onFinished={onViewFinished} />
    </>
  );
};

