const SnapIndicator: React.FC<{ position: THREE.Vector3; type: SnapType; snapEdge?: [THREE.Vector3, THREE.Vector3] }> = ({ position, type, snapEdge }) => {
    if (type === 'grid' || type === 'none') return null;
    let color = '#f59e0b'; let size = 0.08; let geometry = <sphereGeometry args={[size]} />;
    if (type === 'endpoint' || type === 'vertex') { color = '#10b981'; size = 0.12; geometry = <sphereGeometry args={[size]} />; } 
    else if (type === 'midpoint') { color = '#06b6d4'; size = 0.1; geometry = <coneGeometry args={[size, size * 2, 4]} />; } 
    else if (type === 'edge') { color = '#ef4444'; size = 0.06; geometry = <boxGeometry args={[size * 1.5, size * 1.5, size * 1.5]} />; } 
    else if (type === 'face') { color = '#3b82f6'; }
    return (
        <group position={position}>
            {type === 'face' ? (
                 <mesh rotation={[-Math.PI/2, 0, 0]}>
                    <planeGeometry args={[0.2, 0.2]} />
                    <meshBasicMaterial color={color} depthTest={false} transparent opacity={0.5} side={THREE.DoubleSide} />
                    <lineSegments><edgesGeometry args={[new THREE.PlaneGeometry(0.2, 0.2)]} /><lineBasicMaterial color={color} depthTest={false} /></lineSegments>
                 </mesh>
            ) : ( <mesh>{geometry}<meshBasicMaterial color={color} depthTest={false} /></mesh> )}
            {type === 'edge' && snapEdge && ( <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#ef4444" lineWidth={3} depthTest={false} /> )}
            {type === 'midpoint' && snapEdge && ( <SimpleLine points={[snapEdge[0], snapEdge[1]]} color="#06b6d4" lineWidth={3} depthTest={false} /> )}
        </group>
    );
};

const CursorTooltip: React.FC<{ text: string; position: THREE.Vector3; type?: SnapType }> = ({ text, position, type }) => {
    if (type === 'grid' || type === 'none') return null;
    let displayType = ''; let bgColor = 'bg-slate-900/80'; let textColor = 'text-white';
    switch(type) {
        case 'vertex': displayType = '節點 (Node)'; bgColor = 'bg-emerald-600'; break;
        case 'endpoint': displayType = '端點 (Endpoint)'; bgColor = 'bg-emerald-600'; break;
        case 'midpoint': displayType = '中點 (Midpoint)'; bgColor = 'bg-cyan-600'; break;
        case 'edge': displayType = '邊緣 (Edge)'; bgColor = 'bg-red-500'; break;
        case 'face': displayType = '表面 (Face)'; bgColor = 'bg-blue-600'; break;
        case 'align': displayType = '對齊 (Align)'; bgColor = 'bg-pink-500'; break;
        default: displayType = '';
    }
    const displayText = displayType ? (text ? `${displayType}: ${text}` : displayType) : text;
    return (
        <Html position={[position.x, position.y + 0.5, position.z]} center style={{ pointerEvents: 'none', zIndex: 100 }}>
            <div className={`${bgColor} ${textColor} text-xs px-3 py-1.5 rounded-full shadow-lg backdrop-blur-sm border border-white/20 whitespace-nowrap flex items-center gap-2 font-bold transform -translate-y-2`}>{displayText}</div>
        </Html>
    );
};

// ... useShapeDrag (Assumed Present) ...
const useShapeDrag = (
    shape: IShape,
    shapes: IShape[],
    isSelected: boolean,
    tool: ToolType,
    updateShapes: (updates: { id: string; changes: Partial<IShape> }[]) => void,
    setDraggingState: (isDragging: boolean) => void,
    selectedIds: string[],
    shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>,
    setAlignmentLines: (lines: AlignmentLine[]) => void
) => {
    const { camera, gl } = useThree();
    const groupRef = useRef<THREE.Group>(null);
    const dragInfo = useRef({ startPoint: new THREE.Vector3(), originalPositions: {} as Record<string, THREE.Vector3>, isDragging: false });
    const getGroundIntersection = (clientX: number, clientY: number) => {
        const plane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
        const raycaster = new THREE.Raycaster();
        const ndc = new THREE.Vector2((clientX / gl.domElement.clientWidth) * 2 - 1, -(clientY / gl.domElement.clientHeight) * 2 + 1);
        raycaster.setFromCamera(ndc, camera);
        const target = new THREE.Vector3();
        const hit = raycaster.ray.intersectPlane(plane, target);
        return hit ? target : null;
    };
    const handlePointerMove = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect) {
             const rawDelta = new THREE.Vector3().subVectors(intersect, dragInfo.current.startPoint);
             const myOriginalPos = dragInfo.current.originalPositions[shape.id];
             if (!myOriginalPos) return;
             const targetPos = new THREE.Vector3().addVectors(myOriginalPos, rawDelta);
             let snappedX = Math.round(targetPos.x / SNAP_GRID) * SNAP_GRID;
             let snappedZ = Math.round(targetPos.z / SNAP_GRID) * SNAP_GRID;
             const snappedPos = new THREE.Vector3(snappedX, myOriginalPos.y, snappedZ);
             const effectiveDelta = new THREE.Vector3().subVectors(snappedPos, myOriginalPos);
             Object.entries(dragInfo.current.originalPositions).forEach(([id, origPos]) => {
                 const ref = shapeRefs.current[id];
                 if (ref) { ref.position.copy(origPos).add(effectiveDelta); }
             });
        }
    }, [camera, gl, shape.id, shapes, selectedIds]);
    const handlePointerUp = useCallback((e: PointerEvent) => {
        if (!dragInfo.current.isDragging) return;
        document.body.style.cursor = 'default';
        dragInfo.current.isDragging = false;
        setDraggingState(false);
        setAlignmentLines([]);
        window.removeEventListener('pointermove', handlePointerMove);
        window.removeEventListener('pointerup', handlePointerUp);
        const updates = Object.keys(dragInfo.current.originalPositions).map(id => {
            const ref = shapeRefs.current[id];
            if (ref) { return { id, changes: { position: [ref.position.x, ref.position.y, ref.position.z] as [number, number, number] } }; }
            return null;
        }).filter(Boolean) as { id: string, changes: Partial<IShape> }[];
        if (updates.length > 0) { updateShapes(updates); }
    }, [handlePointerMove, updateShapes, setDraggingState, setAlignmentLines]);
    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.SELECT || e.button !== 0) return;
        e.stopPropagation();
        const intersect = getGroundIntersection(e.clientX, e.clientY);
        if (intersect && groupRef.current) {
            dragInfo.current.isDragging = true;
            dragInfo.current.startPoint.copy(intersect);
            let idsToMove: string[] = [];
            if (isSelected) { idsToMove = [...selectedIds]; } 
            else { if (shape.groupId) { idsToMove = shapes.filter(s => s.groupId === shape.groupId).map(s => s.id); } else { idsToMove = [shape.id]; } }
            if (!idsToMove.includes(shape.id)) idsToMove.push(shape.id);
            const origins: Record<string, THREE.Vector3> = {};
            idsToMove.forEach(id => { const ref = shapeRefs.current[id]; if (ref) { origins[id] = ref.position.clone(); } });
            dragInfo.current.originalPositions = origins;
            document.body.style.cursor = 'move';
            setDraggingState(true);
            window.addEventListener('pointermove', handlePointerMove);
            window.addEventListener('pointerup', handlePointerUp);
        }
    }, [tool, shape, shapes, camera, gl, handlePointerMove, handlePointerUp, setDraggingState, isSelected, selectedIds]);
    useEffect(() => { return () => { window.removeEventListener('pointermove', handlePointerMove); window.removeEventListener('pointerup', handlePointerUp); }; }, [handlePointerMove, handlePointerUp]);
    return { groupRef, handlePointerDown };
};

const ShapeRenderer = React.memo(({ shape, isSelected, onSelect, pushPullState, pushPullHandlers, drawingHandlers, setDraggingState, setShapeRef, shapeRefs, setAlignmentLines }: ShapeRendererProps & { shapeRefs: React.MutableRefObject<Record<string, THREE.Group | null>>, setAlignmentLines: (lines: AlignmentLine[]) => void }) => {
    const { unit, tool, updateShapes, layers, selectedIds, shapes } = useApp();
    const parentLayer = layers.find(l => l.id === shape.layerId);
    if (parentLayer && !parentLayer.visible) return null;
    if (shape.type === 'dimension') { return ( <DimensionShape shape={shape} isSelected={isSelected} onSelect={(e) => { if (!isSelected) onSelect(e); }} /> ); }
    const isPushPullMode = tool === ToolType.PUSH_PULL;
    const highlightColor = isPushPullMode ? shape.color : (isSelected ? HIGHLIGHT_COLOR : shape.color);
    const { groupRef, handlePointerDown } = useShapeDrag(shape, shapes, isSelected, tool, updateShapes, setDraggingState, selectedIds, shapeRefs, setAlignmentLines);
    useLayoutEffect(() => { setShapeRef(groupRef.current); return () => setShapeRef(null); }, [setShapeRef, shape.id]);
    const isDraggingTop = pushPullState.mode === 'top' && pushPullState.hoveredShapeId === shape.id && !!pushPullState.dragStartPoint;
    let scaleY = 1;
    if (isDraggingTop && pushPullState.dragHeight !== undefined && shape.height > 0) { scaleY = pushPullState.dragHeight / shape.height; }

    // Updated: Pass holes to createThreeShape
    const shape2D = useMemo(() => createThreeShape(shape.points, shape.holes), [shape.points, shape.holes]);

    return (
        <group 
            ref={groupRef}
            position={[shape.position[0], shape.position[1], shape.position[2]]} 
            rotation={[0, shape.rotation, 0]} 
            scale={[shape.scale[0], shape.scale[1] * scaleY, shape.scale[2]]} 
            userData={{ isShape: true, id: shape.id, isContainer: true }} 
            name="shape_group" 
            onPointerDown={(e) => { if (isPushPullMode) { pushPullHandlers.handlePointerDown(e); } else if (tool === ToolType.SELECT) { if (!isSelected) { onSelect(e); } handlePointerDown(e); } else { drawingHandlers.handlePointerDown(e); } }}
            onPointerMove={(e) => { if (isPushPullMode) { pushPullHandlers.handlePointerMove(e); } }}
            onPointerUp={(e) => { if (isPushPullMode) { pushPullHandlers.handlePointerUp(); } else { drawingHandlers.handlePointerUp(e); } }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} castShadow receiveShadow userData={{ isShape: true, id: shape.id }}>
                <extrudeGeometry args={[shape2D, { depth: shape.height, bevelEnabled: false }]} />
                <meshStandardMaterial color={highlightColor} transparent={shape.type === 'flat'} opacity={shape.type === 'flat' ? 0.6 : 1.0} polygonOffset={shape.type === 'flat'} polygonOffsetFactor={shape.type === 'flat' ? -1 : 0} />
                <Edges color="#333" threshold={15} renderOrder={1000} visible={!isPushPullMode} />
            </mesh>
        </group>
    );
});

// ... Gizmo & Helper Components ... (SelectionGizmo, CameraHandler) - Assumed Present

// ... Drawing Preview ... (Assumed Present)

// ... InteractionLayer ... (Assumed Present)

// ... usePushPullManager ... (Assumed Present)

const useDrawingManager = () => {
    const { tool, addShape, updateShape, shapes, setTool, addGuideLine, unit, wallThickness, formatValue, activeLayerId } = useApp();
    const [drawPoints, setDrawPoints] = useState<IPoint[]>([]);
    const [cursorPos, setCursorPos] = useState(new THREE.Vector3());
    const [snapInfo, setSnapInfo] = useState<SnapResult | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [typedInput, setTypedInput] = useState('');

    // For Measure Tool - Creating Guide Lines
    const [guideCreating, setGuideCreating] = useState<{ active: boolean, start: THREE.Vector3, current: THREE.Vector3, edge: [THREE.Vector3, THREE.Vector3] | null }>({
        active: false,
        start: new THREE.Vector3(),
        current: new THREE.Vector3(),
        edge: null
    });

    const createShapeFromPoints = useCallback((points: IPoint[], type: 'solid' | 'flat' | 'dimension', height: number = 0, name: string) => {
         // Logic to detect if we are drawing INSIDE another shape (Cutting a Hole)
         // Only apply for flat/solid shapes that are closed polygons
         if (type !== 'dimension' && points.length > 2) {
             const parentShape = shapes.find(s => {
                 if (s.type === 'dimension' || s.name === 'Edge') return false;
                 // Quick Check: Bounding box first
                 // Then strict point in polygon check

                 // Transform existing shape points to world space
                 const worldPoly = s.points.map(p => transformPoint(p, s));

                 // Check if ALL new points are inside this polygon
                 // Note: We ignore height/Y check for simplicity, assuming drawing on ground plane or 'on top' logic
                 // For stricter logic, we could check if y matches s.position[1] + s.height
                 return points.every(np => isPointInPolygon({x: np.x, z: np.z}, worldPoly.map(wp => ({x: wp.x, z: wp.z}))));
             });

             if (parentShape) {
                 // It's a hole!
                 // We need to convert the world points 'points' back to the local space of 'parentShape'
                 const localHolePoints = points.map(p => inverseTransformPoint(p, parentShape));

                 const newHoles = parentShape.holes ? [...parentShape.holes, localHolePoints] : [localHolePoints];
                 updateShape(parentShape.id, { holes: newHoles });
                 return; // Stop here, don't create new shape
             }
         }

         // Normal creation
         const shape: IShape = {
             id: `shape-${Date.now()}`,
             layerId: activeLayerId,
             type,
             points: points.map(p => ({ x: p.x, y: 0, z: p.z })),
             height,
             color: type === 'flat' ? FLAT_COLOR : DEFAULT_COLOR,
             position: [0, 0, 0],
             rotation: 0,
             scale: [1, 1, 1],
             name
         };
         addShape(shape);
    }, [activeLayerId, addShape, shapes, updateShape]);

    const handlePointAdd = useCallback((point: THREE.Vector3) => {
        const p: IPoint = { x: point.x, y: 0, z: point.z };
        const newPoints = [...drawPoints, p];

        if (tool === ToolType.DRAW_LINE) {
            if (newPoints.length === 2) {
                const start = new THREE.Vector3(newPoints[0].x, 0, newPoints[0].z);
                const end = new THREE.Vector3(newPoints[1].x, 0, newPoints[1].z);
                const vec = end.clone().sub(start);
                const len = vec.length();
                if (len > 0.01) {
                    const dir = vec.normalize();
                    const perp = new THREE.Vector3(-dir.z, 0, dir.x).multiplyScalar(wallThickness / 2);

                    const p1 = start.clone().add(perp);
                    const p2 = end.clone().add(perp);
                    const p3 = end.clone().sub(perp);
                    const p4 = start.clone().sub(perp);

                    createShapeFromPoints([p1, p2, p3, p4], 'solid', 2.5, 'Wall');
                }
                setDrawPoints([]);
            } else {
                setDrawPoints(newPoints);
            }
        } else if (tool === ToolType.DRAW_RECT) {
             if (newPoints.length === 2) {
                 const p1 = newPoints[0];
                 const p2 = newPoints[1];
                 const minX = Math.min(p1.x, p2.x);
                 const maxX = Math.max(p1.x, p2.x);
                 const minZ = Math.min(p1.z, p2.z);
                 const maxZ = Math.max(p1.z, p2.z);

                 const pts = [
                     { x: minX, y: 0, z: minZ },
                     { x: maxX, y: 0, z: minZ },
                     { x: maxX, y: 0, z: maxZ },
                     { x: minX, y: 0, z: maxZ },
                     { x: minX, y: 0, z: minZ }
                 ];
                 createShapeFromPoints(pts, 'flat', DEFAULT_HEIGHT, 'Room/Floor');
                 setDrawPoints([]);
             } else {
                 setDrawPoints(newPoints);
             }
        } else if (tool === ToolType.DRAW_CIRCLE) {
             if (newPoints.length === 2) {
                 const center = newPoints[0];
                 const edge = newPoints[1];
                 const radius = Math.sqrt((edge.x - center.x)**2 + (edge.z - center.z)**2);
                 const circlePts = createCirclePoints(radius);

                 const finalPts = circlePts.map(cp => ({ x: cp.x + center.x, y: 0, z: cp.z + center.z }));
                 createShapeFromPoints(finalPts, 'flat', DEFAULT_HEIGHT, 'Circle');
                 setDrawPoints([]);
             } else {
                 setDrawPoints(newPoints);
             }
        } else if (tool === ToolType.MEASURE) {
            // ... measure logic (unchanged) ...
            if (guideCreating.active) {
                if (guideCreating.edge) {
                     const p1 = guideCreating.edge[0];
                     const p2 = guideCreating.edge[1];
                     const dir = new THREE.Vector3().subVectors(p2, p1).normalize();
                     const start = point.clone().sub(dir.clone().multiplyScalar(100));
                     const end = point.clone().add(dir.clone().multiplyScalar(100));

                     addGuideLine({
                         id: `guide-${Date.now()}`,
                         points: [[start.x, start.y, start.z], [end.x, end.y, end.z]]
                     });
                }
                setGuideCreating({ active: false, start: new THREE.Vector3(), current: new THREE.Vector3(), edge: null });
                setDrawPoints([]);
            } else {
                 if (snapInfo && (snapInfo.type === 'edge' || snapInfo.type === 'midpoint') && snapInfo.snapEdge) {
                     setGuideCreating({
                         active: true,
                         start: point,
                         current: point,
                         edge: snapInfo.snapEdge
                     });
                 } else {
                     if (newPoints.length === 2) {
                        createShapeFromPoints([newPoints[0], newPoints[1], {x: point.x, y: 0, z: point.z}], 'dimension', 0, 'Dimension');
                        setDrawPoints([]);
                     } else {
                        setDrawPoints(newPoints);
                     }
                 }
            }
        }
    }, [drawPoints, tool, wallThickness, createShapeFromPoints, guideCreating, snapInfo, addGuideLine]);

    const finishDrawingWithInput = useCallback((val: number) => {
         if (drawPoints.length === 0) return;
         const lastPoint = drawPoints[drawPoints.length - 1];
         const start = new THREE.Vector3(lastPoint.x, lastPoint.y, lastPoint.z);
         const dir = new THREE.Vector3().subVectors(cursorPos, start).normalize();
         if (dir.lengthSq() === 0) dir.set(1, 0, 0); 
         const target = start.clone().add(dir.multiplyScalar(unit === 'cm' ? val / 100 : val));
         handlePointAdd(target);
    }, [drawPoints, cursorPos, unit, handlePointAdd]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            if (tool === ToolType.SELECT || tool === ToolType.PUSH_PULL) return;
            if (/^[0-9.]$/.test(e.key)) {
                setTypedInput(prev => prev + e.key);
            } else if (e.key === 'Backspace') {
                setTypedInput(prev => prev.slice(0, -1));
            } else if (e.key === 'Enter') {
                if (typedInput) {
                    finishDrawingWithInput(parseFloat(typedInput));
                    setTypedInput('');
                }
            } else if (e.key === 'Escape') {
                setDrawPoints([]);
                setTypedInput('');
                setGuideCreating(prev => ({ ...prev, active: false }));
            }
        };
        window.addEventListener('keydown', handleKeyDown);
        return () => window.removeEventListener('keydown', handleKeyDown);
    }, [tool, typedInput, finishDrawingWithInput]);

    const handlePointerDown = (e: ThreeEvent<PointerEvent>) => {
        if (e.button !== 0) return;
        const target = snapInfo ? snapInfo.position : e.point;
        handlePointAdd(target);
    };
    const handlePointerUp = (e: ThreeEvent<PointerEvent>) => {};
    const handleClick = (e: ThreeEvent<MouseEvent>) => {};
    useEffect(() => {
        if (guideCreating.active) {
            setGuideCreating(prev => ({ ...prev, current: cursorPos }));
        }
    }, [cursorPos, guideCreating.active]);

    return { drawPoints, cursorPos, setCursorPos, snapInfo, setSnapInfo, isDragging, handlePointerDown, handlePointerUp, handleClick, typedInput, guideCreating };
};

// ... EditorContent, Viewport (Main components) ... (Assumed present and wrapping the above)
const EditorContent: React.FC<{ view: string | null; onViewFinished: () => void }> = ({ view, onViewFinished }) => {
  const { shapes, tool, selectedIds, selectShape, updateShapes, guideLines } = useApp();
  const [alignmentLines, setAlignmentLines] = useState<AlignmentLine[]>([]);
  const shapeRefs = useRef<Record<string, THREE.Group | null>>({});
  const [isShapeDragging, setIsShapeDragging] = useState(false);
  const setShapeRef = useCallback((id: string, ref: THREE.Group | null) => { shapeRefs.current[id] = ref; }, []);
  const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, isDragging: isPPDragging } = usePushPullManager();
  const { drawPoints, cursorPos: drawCursorPos, setCursorPos: setDrawCursorPos, snapInfo: drawSnapInfo, setSnapInfo: setDrawSnapInfo, isDragging: isDrawDragging, handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, handleClick: handleDrawClick, typedInput, guideCreating } = useDrawingManager();
  const isOrbitEnabled = (tool === ToolType.SELECT && !isShapeDragging) || (tool === ToolType.PUSH_PULL && !isPPDragging) || (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && !isDrawDragging);

  return (
    <>
        <ambientLight intensity={0.7} />
        <directionalLight position={[10, 20, 10]} intensity={1.2} castShadow shadow-mapSize={[2048, 2048]} />
        <Grid infiniteGrid fadeDistance={50} sectionColor="#cbd5e1" cellColor="#e2e8f0" sectionSize={1} cellSize={0.1} />
        <OrbitControls makeDefault enabled={isOrbitEnabled} minDistance={2} maxDistance={50} dampingFactor={0.1}/>
        <group 
            onPointerDown={(e) => { if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) { handleDrawDown(e); } else { selectShape('', false); } }} 
            onPointerUp={(e) => { if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) handleDrawUp(e); if (tool === ToolType.PUSH_PULL) handlePPUp(); }}
            onPointerMove={(e) => { if (tool === ToolType.PUSH_PULL) handlePPMove(e); }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow><planeGeometry args={[1000, 1000]} /><meshBasicMaterial visible={false} /></mesh>
        </group>
        <group>
          {shapes.map(shape => (
            <ShapeRenderer key={shape.id} shape={shape} isSelected={selectedIds.includes(shape.id)} onSelect={(e) => { e.stopPropagation(); const isMulti = e.nativeEvent.ctrlKey || e.nativeEvent.metaKey; selectShape(shape.id, isMulti); }} pushPullState={ppState} pushPullHandlers={{ handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, handlePointerMove: handlePPMove }} drawingHandlers={{ handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, handleClick: handleDrawClick }} setDraggingState={setIsShapeDragging} setShapeRef={(ref) => setShapeRef(shape.id, ref)} shapeRefs={shapeRefs} setAlignmentLines={setAlignmentLines} />
          ))}
        </group>
        <InteractionLayer shapes={shapes} tool={tool} setCursorPos={setDrawCursorPos} setSnapInfo={setDrawSnapInfo} cursorPos={drawCursorPos} snapInfo={drawSnapInfo} drawPoints={drawPoints} isDragging={isDrawDragging} drawingHeight={0} typedInput={typedInput} guideCreating={guideCreating} />
        <AlignmentLinesRenderer lines={alignmentLines} />
        <GuideLinesRenderer lines={guideLines} />
        <SelectionGizmo />
        <GizmoHelper alignment="bottom-right" margin={[80, 80]}><GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" /></GizmoHelper>
        <CameraHandler view={view} onFinished={onViewFinished} />
    </>
  );
};

const Viewport: React.FC = () => {
  const { tool, deselectAll, cameraView, setCameraView } = useApp();
  return (
    <div className="w-full h-full bg-slate-50 relative cursor-crosshair">
      <Canvas shadows camera={{ position: [5, 5, 5], fov: 50 }} gl={{ preserveDrawingBuffer: true, antialias: true }} onPointerMissed={(e) => { if (tool === ToolType.SELECT && e.type === 'click') { deselectAll(); } }}>
        <color attach="background" args={['#f8fafc']} />
        <EditorContent view={cameraView} onViewFinished={() => setCameraView(null)} />
      </Canvas>
    </div>
  );
};

export default Viewport;

