import React, { useRef, useState, useEffect } from 'react';
import { Canvas, useFrame, useThree, extend, useLoader } from '@react-three/fiber';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { TransformControls } from 'three/examples/jsm/controls/TransformControls';
import * as THREE from 'three';
import { useGesture } from '@use-gesture/react';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader';

extend({ OrbitControls, TransformControls });

// Assume these imports are properly defined
import { usePushPullManager } from './usePushPullManager';
// import { InteractionLayer } from './InteractionLayer';
// import { SelectionGizmo } from './SelectionGizmo';
// import { CameraHandler } from './CameraHandler';

interface ViewportProps {
    modelUrl: string;
    onModelLoad: (model: THREE.Group) => void;
    tool: string;
    shapes: any[]; // replace any with specific shape type
    onShapeCreated: (shape: any) => void; // replace any with specific shape type
    snapInfo: any; // replace any with specific type
    typedInput: string;
    guideCreating: boolean;
    onShapeUpdated: (shape: any) => void;
    view: string | null;
    onFinished: () => void;
}

const Viewport: React.FC<ViewportProps> = ({
    modelUrl,
    onModelLoad,
    tool,
    shapes,
    onShapeCreated,
    snapInfo,
    typedInput,
    guideCreating,
    onShapeUpdated,
    view,
    onFinished,
}) => {
    const [cursorPos, setCursorPos] = useState({ x: 0, y: 0, z: 0 });
    const [drawPoints, setDrawPoints] = useState<THREE.Vector3[]>([]);
    const [selectedObject, setSelectedObject] = useState<THREE.Object3D | null>(null);
    const [isDragging, setIsDragging] = useState(false); // Add dragging state

    const { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging: pushPullDragging } = usePushPullManager(); // rename pushPullDragging
    const viewportRef = useRef<HTMLDivElement>(null);
