const usePushPullManager = () => {
    const { tool, shapes, updateShape } = useApp();
    const [ppState, setPpState] = useState<PushPullState>({
        mode: 'none',
        hoveredShapeId: null,
        hoveredEdgeIndex: -1,
        dragStartPoint: null,
        originalHeight: 0,
        originalPoints: [],
        normal: new THREE.Vector3(0, 1, 0)
    });
    const [isDragging, setIsDragging] = useState(false);

    const handlePointerMove = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL) return;

        if (isDragging && ppState.hoveredShapeId && ppState.dragStartPoint) {
            const shape = shapes.find(s => s.id === ppState.hoveredShapeId);
            if (shape) {
                const dy = e.point.y - ppState.dragStartPoint.y;
                const newHeight = Math.max(0.01, ppState.originalHeight + dy);
                setPpState(prev => ({ ...prev, dragHeight: newHeight }));
            }
            return;
        }

        if (e.object.userData?.isShape) {
            const shapeId = e.object.userData.id;
            if (ppState.hoveredShapeId !== shapeId) {
                const shape = shapes.find(s => s.id === shapeId);
                setPpState({
                    mode: 'top',
                    hoveredShapeId: shapeId,
                    hoveredEdgeIndex: -1,
                    dragStartPoint: null,
                    originalHeight: shape?.height || 0,
                    originalPoints: shape?.points || [],
                    normal: new THREE.Vector3(0,1,0)
                });
            }
        } else {
             if (ppState.hoveredShapeId && !isDragging) {
                 setPpState(prev => ({ ...prev, hoveredShapeId: null, mode: 'none' }));
             }
        }
    }, [tool, isDragging, ppState, shapes]);

    const handlePointerDown = useCallback((e: ThreeEvent<PointerEvent>) => {
        if (tool !== ToolType.PUSH_PULL || !ppState.hoveredShapeId) return;
        e.stopPropagation();
        setIsDragging(true);
        setPpState(prev => ({ ...prev, dragStartPoint: e.point.clone(), dragHeight: prev.originalHeight }));
    }, [tool, ppState]);

    const handlePointerUp = useCallback(() => {
        if (isDragging && ppState.hoveredShapeId && ppState.dragHeight !== undefined) {
             updateShape(ppState.hoveredShapeId, { height: ppState.dragHeight });
        }
        setIsDragging(false);
        setPpState(prev => ({ ...prev, dragStartPoint: null, dragHeight: undefined }));
    }, [isDragging, ppState, updateShape]);

    return { ppState, handlePointerMove, handlePointerDown, handlePointerUp, isDragging };
};

