  const { ppState, handlePointerMove: handlePPMove, handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, isDragging: isPPDragging } = usePushPullManager();
  const { drawPoints, cursorPos: drawCursorPos, setCursorPos: setDrawCursorPos, snapInfo: drawSnapInfo, setSnapInfo: setDrawSnapInfo, isDragging: isDrawDragging, handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, handleClick: handleDrawClick, typedInput, guideCreating } = useDrawingManager();
  const isOrbitEnabled = (tool === ToolType.SELECT && !isShapeDragging) || (tool === ToolType.PUSH_PULL && !isPPDragging) || (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL && !isDrawDragging);

  return (
    <>
        <ambientLight intensity={0.7} />
        <directionalLight position={[10, 20, 10]} intensity={1.2} castShadow shadow-mapSize={[2048, 2048]} />
        <Grid infiniteGrid fadeDistance={50} sectionColor="#cbd5e1" cellColor="#e2e8f0" sectionSize={1} cellSize={0.1} />
        <OrbitControls makeDefault enabled={isOrbitEnabled} minDistance={2} maxDistance={50} dampingFactor={0.1}/>
        <group 
            onPointerDown={(e) => { if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) { handleDrawDown(e); } else { selectShape('', false); } }} 
            onPointerUp={(e) => { if (tool !== ToolType.SELECT && tool !== ToolType.PUSH_PULL) handleDrawUp(e); if (tool === ToolType.PUSH_PULL) handlePPUp(); }}
            onPointerMove={(e) => { if (tool === ToolType.PUSH_PULL) handlePPMove(e); }}
        >
            <mesh rotation={[-Math.PI/2, 0, 0]} position={[0, -0.02, 0]} receiveShadow><planeGeometry args={[1000, 1000]} /><meshBasicMaterial visible={false} /></mesh>
        </group>
        <group>
          {shapes.map(shape => (
            <ShapeRenderer key={shape.id} shape={shape} isSelected={selectedIds.includes(shape.id)} onSelect={(e) => { e.stopPropagation(); const isMulti = e.nativeEvent.ctrlKey || e.nativeEvent.metaKey; selectShape(shape.id, isMulti); }} pushPullState={ppState} pushPullHandlers={{ handlePointerDown: handlePPDown, handlePointerUp: handlePPUp, handlePointerMove: handlePPMove }} drawingHandlers={{ handlePointerDown: handleDrawDown, handlePointerUp: handleDrawUp, handleClick: handleDrawClick }} setDraggingState={setIsShapeDragging} setShapeRef={(ref) => setShapeRef(shape.id, ref)} shapeRefs={shapeRefs} setAlignmentLines={setAlignmentLines} />
          ))}
        </group>
        <InteractionLayer shapes={shapes} tool={tool} setCursorPos={setDrawCursorPos} setSnapInfo={setDrawSnapInfo} cursorPos={drawCursorPos} snapInfo={drawSnapInfo} drawPoints={drawPoints} isDragging={isDrawDragging} drawingHeight={0} typedInput={typedInput} guideCreating={guideCreating} />
        <AlignmentLinesRenderer lines={alignmentLines} />
        <GuideLinesRenderer lines={guideLines} />
        <SelectionGizmo />
        <GizmoHelper alignment="bottom-right" margin={[80, 80]}><GizmoViewport axisColors={['#ef4444', '#22c55e', '#3b82f6']} labelColor="white" /></GizmoHelper>
